import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ============================================================================
  // 1. BUILD STAGE BACKDROP
  // ============================================================================
  const stageGroup = new THREE.Group();
  stageGroup.name = 'pricing-title-stage';

  const stagePlaneGeom = new THREE.PlaneGeometry(7, 6);
  const stageMatNode = new MeshBasicNodeMaterial();
  const stageMatGradient = mix(
    vec3(0.067, 0.067, 0.063), // surface #0b0b10
    vec3(0.086, 0.086, 0.094), // ink #16161d with subtle lift
    uv().y
  );
  stageMatNode.colorNode = stageMatGradient;
  const stagePlane = new THREE.Mesh(stagePlaneGeom, stageMatNode);
  stagePlane.position.z = -2.5;
  stagePlane.renderOrder = 0;
  stageGroup.add(stagePlane);

  // ============================================================================
  // 2. LOAD IMAGE TEXTURE & CREATE CONTENT PLANE
  // ============================================================================
  const contentGroup = new THREE.Group();
  contentGroup.name = 'pricing-title-content';

  let textureResource = null;
  let contentPlane = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      textureResource = tex;
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.magFilter = THREE.LinearFilter;
      tex.minFilter = THREE.LinearMipmapLinearFilter;

      // Create material with texture
      const contentMat = new MeshBasicNodeMaterial();
      contentMat.colorNode = texture(tex);
      contentMat.transparent = true;

      // Plane dimensions: maintain aspect ratio from 512x320 (1.6:1)
      const planeWidth = 3.2;
      const planeHeight = 2.0;
      const planeGeom = new THREE.PlaneGeometry(planeWidth, planeHeight);

      contentPlane = new THREE.Mesh(planeGeom, contentMat);
      contentPlane.position.z = 0.1;
      contentPlane.renderOrder = 1;
      contentGroup.add(contentPlane);
    });
  }

  // ============================================================================
  // 3. RENDER TEXT HEADLINE ("Pricing")
  // ============================================================================
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const pricingTextItem = textItems.find((item) => item.text === 'Pricing') || {
    text: 'Pricing',
    role: 'headline',
    typography: { fontSize: 96 },
  };

  const headlineObj = ctx.fontAtlas.createText(String(pricingTextItem.text), {
    fontSize: pricingTextItem.typography?.fontSize ?? 96,
    color: '#e8ecf2', // paper
    align: 'center',
  });
  headlineObj.position.set(0, 0.8, 0.2);
  headlineObj.renderOrder = 2;
  contentGroup.add(headlineObj);

  // ============================================================================
  // 4. ASSEMBLE NODE
  // ============================================================================
  const node = new THREE.Group();
  node.name = 'pricing-title-node';
  node.add(stageGroup);
  node.add(contentGroup);

  // Apply scenePosition (adapter will also apply, but be explicit here if needed)
  if (config.scenePosition) {
    node.position.copy(config.scenePosition);
  }

  // ============================================================================
  // 5. CLEANUP
  // ============================================================================
  node.userData.cleanup = () => {
    stagePlaneGeom.dispose();
    stageMatNode.dispose();
    if (textureResource) {
      textureResource.dispose();
    }
    if (contentPlane) {
      contentPlane.geometry.dispose();
      contentPlane.material.dispose();
    }
    // fontAtlas text is managed by the system
  };

  return node;
}
